      'É representada frequentemente com uma serpente no útero — símbolo da fertilização por um ser sobrenatural/caído.',
      'Crop circles em Wiltshire, Reino Unido, foram interpretados como representações da fertilização do corpo de Gaia na própria terra, com espermatozoides de "sementes de serpentes aladas".',
      'A topografia de Wiltshire (Milk Hill, Silbury Hill, Woodborough Hill) foi mapeada como correspondente ao corpo anatômico da deusa, com as colinas representando seios.',
